61	// WithCheckpointRemoteBootstrap marks ctx as permitting EnsurePrimaryRef to
62	// fetch a missing primary metadata ref from a configured checkpoint_remote.
63	// This must only be set on explicit, user-initiated setup flows (`entire
64	// enable`, agent add/setup) — never on the per-turn hook hot path. EnsureSetup
65	// runs synchronously on every TurnStart hook and hook execution has a hard
66	// timeout; without this guard a slow/unreachable checkpoint remote would
67	// repeat an expensive fetch on every turn instead of self-healing once via
68	// the empty-orphan fallback.
69	func WithCheckpointRemoteBootstrap(ctx context.Context) context.Context {
70		return context.WithValue(ctx, checkpointRemoteBootstrapContextKey{}, true)
71	}
72	
73	// checkpointRemoteBootstrapAllowed reports whether ctx was marked via
74	// WithCheckpointRemoteBootstrap.
75	func checkpointRemoteBootstrapAllowed(ctx context.Context) bool {
76		v := ctx.Value(checkpointRemoteBootstrapContextKey{})
77		allowed, ok := v.(bool)
78		return ok && allowed
79	}
80	
81	// IsEmptyRepository returns true if the repository has no commits yet.
82	// After git-init, HEAD points to an unborn branch (e.g., refs/heads/main)
83	// whose target does not yet exist. repo.Head() returns ErrReferenceNotFound
84	// in this case.
85	func IsEmptyRepository(repo *git.Repository) bool {
86		_, err := repo.Head()
87		return errors.Is(err, plumbing.ErrReferenceNotFound)
88	}
